"use client";

import { Button, ButtonSize, ButtonVariant } from "@dooph-software/design-system";

declare global {
  interface Window {
    Intercom?: (...args: unknown[]) => void;
  }
}

export function TalkToSalesButton() {
  return (
    <Button
      variant={ButtonVariant.secondary}
      size={ButtonSize.big}
      onClick={() => window.Intercom?.("show")}
    >
      Talk to sales
    </Button>
  );
}

